import{_ as o,C as i,o as t,c as s,a2 as e,b as n,w as r,a as A,E as u,a3 as E}from"./chunks/framework.BBdhqAg0.js";const g="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",b=JSON.parse('{"title":"사용자 관리 (User Management)","description":"","frontmatter":{},"headers":[],"relativePath":"work-setting/user.md","filePath":"work-setting/user.md","lastUpdated":1793112345000}'),B={name:"work-setting/user.md"};function C(d,a,c,m,h,_){const l=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="사용자-관리-user-management" tabindex="-1">사용자 관리 (User Management) <a class="header-anchor" href="#사용자-관리-user-management" aria-label="Permalink to &quot;사용자 관리 (User Management)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+g+'" alt="사용자 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/user.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>사용자 관리</strong> 페이지는 시스템 관리자가 전사 임직원의 계정을 발급하고, 활성화 상태 및 관리자 권한을 제어하며, 각 사용자의 업무 부하량·참여 워크스페이스·최근 활동 로그를 다각도로 모니터링하는 종합 계정 센터입니다.</p></blockquote><h2 id="_1-개요-및-계정-운영-흐름" tabindex="-1">1. 개요 및 계정 운영 흐름 <a class="header-anchor" href="#_1-개요-및-계정-운영-흐름" aria-label="Permalink to &quot;1. 개요 및 계정 운영 흐름&quot;">​</a></h2><p>관리자는 신규 입사자의 계정을 발급하고 필요한 워크스페이스에 즉시 역할을 배정할 수 있으며, 특정 사용자의 업무 진행 현황과 활동 내역을 대시보드 형태로 파악할 수 있습니다.</p><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[설정 관리] → [사용자]**를 선택하여 접속합니다. (관리자 권한 필요)</li></ul>',6)),(t(),n(E,null,{default:r(()=>[u(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%F0%9F%91%A4%201.%20%EA%B3%84%EC%A0%95%20%EB%B0%9C%EA%B8%89%3Cbr%3E(%EC%95%84%EC%9D%B4%EB%94%94%C2%B7%EB%9E%9C%EB%8D%A4%20%EC%95%94%ED%98%B8%C2%B7%EC%B4%88%EB%8C%80%20%EB%A9%94%EC%9D%BC)%22%5D%20--%3E%20B%5B%22%F0%9F%8F%A2%202.%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%97%AD%ED%95%A0%20%EB%B0%B0%EC%A0%95%3Cbr%3E(%EB%8B%A4%EC%A4%91%20Role%20%EC%9D%B8%EB%9D%BC%EC%9D%B8%20%EB%B6%80%EC%97%AC)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%93%8A%203.%20%ED%99%9C%EB%8F%99%20%EB%AA%A8%EB%8B%88%ED%84%B0%EB%A7%81%3Cbr%3E(%EC%97%85%EB%AC%B4%20%ED%86%B5%EA%B3%84%C2%B7%EC%B5%9C%EA%B7%BC%20%EC%8B%A4%ED%96%89%20%EB%A1%9C%EA%B7%B8)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%94%92%204.%20%EA%B3%84%EC%A0%95%20%EC%83%9D%EC%95%A0%EC%A3%BC%EA%B8%B0%20%EC%A0%9C%EC%96%B4%3Cbr%3E(%ED%99%9C%EC%84%B1%2F%EB%B9%84%ED%99%9C%EC%84%B1%C2%B7%EB%B9%84%EB%B2%88%20%EC%9E%AC%EC%84%A4%EC%A0%95)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="_2-사용자-목록-그리드-및-필터" tabindex="-1">2. 사용자 목록 그리드 및 필터 <a class="header-anchor" href="#_2-사용자-목록-그리드-및-필터" aria-label="Permalink to &quot;2. 사용자 목록 그리드 및 필터&quot;">​</a></h2><p>전체 사용자의 기본 정보와 시스템 접근 상태를 조회하고 필터링할 수 있습니다.</p><ul><li><strong>계정 식별 정보</strong>: 아이디, 이름, 이메일 주소, 등록일시, 마지막 로그인 시각 (경과 시간 표출)</li><li><strong>계정 상태 배지</strong>: <ul><li><strong>활성 (초록색 배지)</strong>: 정상적으로 로그인하고 시스템을 이용할 수 있는 활성 계정입니다.</li><li><strong>잠금/비활성 (회색 배지)</strong>: 시스템 로그인이 차단된 계정입니다. (퇴사 또는 휴직 처리 시 활용)</li></ul></li><li><strong>관리자 권한 배지</strong>: <ul><li><strong>업무 총괄 관리자 배지</strong>: 모든 워크스페이스(비공개 포함) 및 업무 설정 메뉴를 총괄 제어할 수 있는 최고 업무 권한자입니다.</li><li><strong>관리자 배지</strong>: 관리자 콘솔 및 기본 시스템 관리 화면에 접근할 수 있는 권한자입니다.</li></ul></li></ul><h2 id="_3-관리자-메뉴-계정-편집-및-워크스페이스-배정" tabindex="-1">3. 관리자 메뉴 (계정 편집 및 워크스페이스 배정) <a class="header-anchor" href="#_3-관리자-메뉴-계정-편집-및-워크스페이스-배정" aria-label="Permalink to &quot;3. 관리자 메뉴 (계정 편집 및 워크스페이스 배정)&quot;">​</a></h2><p>사용자 등록 및 편집 화면은 상단 탭을 통해 2개 영역으로 분리되어 제공됩니다.</p><h3 id="📋-1-일반-정보-탭" tabindex="-1">📋 1. 일반 정보 탭 <a class="header-anchor" href="#📋-1-일반-정보-탭" aria-label="Permalink to &quot;📋 1. 일반 정보 탭&quot;">​</a></h3><ul><li><strong>기본 인적 사항</strong>: 사용자 아이디, 한글 성명, 공식 회사 이메일 주소를 등록합니다.</li><li><strong>비밀번호 자동 생성기</strong>: 복잡하고 안전한 임의 비밀번호를 원클릭으로 자동 생성하여 입력할 수 있습니다.</li><li><strong>초대/안내 메일 자동 발송</strong>: <ul><li>새 계정 발급 시 로그인 웹 주소(URL)와 초기 임시 비밀번호 안내 메일이 해당 사용자의 이메일로 자동 전송됩니다. (초기 링크 유효시간: 24시간)</li></ul></li><li><strong>계정 상태 및 권한 제어</strong>: <ul><li><strong>계정 활성화 체크박스</strong>: 체크 해제 시 즉시 로그인이 차단됩니다.</li><li><strong>관리자 여부</strong>: 시스템 관리 콘솔 접근 권한 부여</li><li><strong>업무 총괄 관리자 여부</strong>: 전사 모든 워크스페이스와 설정을 감독할 수 있는 최고 권한 부여</li></ul></li></ul><h3 id="🏢-2-워크스페이스-탭" tabindex="-1">🏢 2. 워크스페이스 탭 <a class="header-anchor" href="#🏢-2-워크스페이스-탭" aria-label="Permalink to &quot;🏢 2. 워크스페이스 탭&quot;">​</a></h3><p>특정 사용자가 참여 중인 모든 워크스페이스를 한 화면에서 일괄 관리합니다.</p><ul><li><strong>다중 역할(Role) 인라인 편집</strong>: 각 워크스페이스별로 부여된 역할(예: <code>업무관리자</code>, <code>개발자</code>, <code>보고자</code> 등)을 인라인 체크박스로 즉시 수정할 수 있습니다.</li><li><strong>새 워크스페이스 참여 추가</strong>: 모달 팝업을 통해 사용자를 새로운 워크스페이스에 초대하고 역할을 즉시 부여합니다.</li><li><strong>워크스페이스 제외</strong>: 프로젝트가 종료되거나 담당 부서가 변경된 경우, 해당 워크스페이스에서 사용자를 즉시 제외 처리합니다.</li></ul><h2 id="_4-사용자-상세-프로필-user-detail-view" tabindex="-1">4. 사용자 상세 프로필 (User Detail View) <a class="header-anchor" href="#_4-사용자-상세-프로필-user-detail-view" aria-label="Permalink to &quot;4. 사용자 상세 프로필 (User Detail View)&quot;">​</a></h2><p>사용자 목록에서 특정 사용자의 행을 클릭하면 해당 임직원의 모든 협업 데이터가 집약된 개인 대시보드로 이동합니다.</p><h3 id="📊-업무-통계-issue-summary" tabindex="-1">📊 업무 통계 (Issue Summary) <a class="header-anchor" href="#📊-업무-통계-issue-summary" aria-label="Permalink to &quot;📊 업무 통계 (Issue Summary)&quot;">​</a></h3><ul><li>사용자에게 할당된 전체 업무 수, <strong>진행 중 업무 건수</strong>, <strong>완료된 업무 건수</strong>를 카드로 시각화하여 현재 업무 부하량과 진척도를 직관적으로 진단합니다.</li></ul><h3 id="🌲-참여-워크스페이스-트리-project-summary" tabindex="-1">🌲 참여 워크스페이스 트리 (Project Summary) <a class="header-anchor" href="#🌲-참여-워크스페이스-트리-project-summary" aria-label="Permalink to &quot;🌲 참여 워크스페이스 트리 (Project Summary)&quot;">​</a></h3><ul><li>상위-하위 워크스페이스 계층 구조와 함께 사용자가 어떤 프로젝트에서 어떤 직무 역할로 참여 중인지 트리 뷰로 조망합니다.</li></ul><h3 id="⏱️-최근-활동-로그-피드-activity-log" tabindex="-1">⏱️ 최근 활동 로그 피드 (Activity Log) <a class="header-anchor" href="#⏱️-최근-활동-로그-피드-activity-log" aria-label="Permalink to &quot;⏱️ 최근 활동 로그 피드 (Activity Log)&quot;">​</a></h3><ul><li>해당 사용자가 최근 등록하거나 수정한 업무, 작성한 댓글, 회의록, 문서 등 <strong>최신 활동 내역 10건</strong>을 타임라인 피드로 실시간 추적합니다. (해당 항목 클릭 시 <a href="/work-manage/activity.html">업무실행내역</a> 상세 페이지로 바로 이동)</li></ul><h2 id="_5-실무-운영-가이드" tabindex="-1">5. 실무 운영 가이드 <a class="header-anchor" href="#_5-실무-운영-가이드" aria-label="Permalink to &quot;5. 실무 운영 가이드&quot;">​</a></h2><ul><li><strong>퇴사 및 인사이동 시 계정 관리 원칙 (필독 ⭐️)</strong>: <ul><li>직원이 퇴사하거나 전출하더라도 <strong>절대로 계정을 시스템에서 임의 삭제하지 마십시오</strong>.</li><li>해당 사용자가 과거에 작성한 기안문, 결재 승인 이력, 회의록, 등록한 업무 데이터의 무결성을 보존하기 위해, 사용자 편집 화면에서 <strong>&#39;계정 활성화&#39; 체크만 해제</strong>하여 비활성화 상태로 보관하십시오.</li></ul></li><li><strong>업무 부하 분산 및 일정 조율</strong>: <ul><li>사용자 상세 프로필의 업무 통계에서 특정 팀원의 &#39;진행 중 업무&#39;가 과다하게 누적되어 있다면, 진행 중인 업무 목록을 검토하여 타 팀원에게 업무를 재배분하거나 일정을 조정하는 리소스 관리 도구로 활용할 수 있습니다.</li></ul></li></ul>',20))])}const D=o(B,[["render",C]]);export{b as __pageData,D as default};
